const pb = global.get("pb");
const conn = msg.connection;

if (!conn) {
    node.warn("No connection on msg for initial timestamp");
    return msg;
}

const lastItem = Array.isArray(msg.payload) && msg.payload.at(-1);
const timestamp = lastItem?.timeCreated || Date.now();

pb.setTimestamp(conn.id, "rayvn", timestamp);
pb.setTimestamp(conn.id, "wasos", Date.now());

return msg;

// ============================================================
// NODE: "Initialize Parat-Bridge"
// TYPE: function
// LOCATION: Parat-Bridge.json
// WIRING: inject (once) → [this] → GUI entrypoint
// Replaces: "set client base urls" + "set initial master_log"
// ============================================================

const BASE_URLS = {
    rayvn: "https://api.rayvn.global",
    wasos: "https://dev.wasos.no"
};

// Keep existing data on restart
let data = global.get("parat_bridge") || null;

if (!data) {
    data = {
        base_urls: BASE_URLS,
        connections: [],
        queue: [],
        master_log: []
    };
} else {
    data.base_urls = BASE_URLS;
    if (!data.queue) data.queue = [];
}

global.set("parat_bridge", data);

// ===== HHelper =====
const pb = {

    // --- Connections ---
    getConnections: function() {
        return global.get("parat_bridge").connections || [];
    },

    getActiveConnections: function() {
        return (global.get("parat_bridge").connections || []).filter(c => c.active);
    },

    getConnection: function(connectionId) {
        return (global.get("parat_bridge").connections || []).find(c => c.id === connectionId) || null;
    },

    addConnection: function(rayvnConfig, wasosConfig) {
        const d = global.get("parat_bridge");
        const connId = "conn_" + (d.connections.length + 1) + "_" + Date.now().toString(36);
        const label = (rayvnConfig.log_name || "Rayvn") + " ↔ " + (wasosConfig.chatroom_name || "WaSOS");

        const conn = {
            id: connId,
            label: label,
            rayvn: {
                api_key: rayvnConfig.api_key,
                log_name: rayvnConfig.log_name,
                log_id: rayvnConfig.log_id
            },
            wasos: {
                username: wasosConfig.username,
                chatroom_name: wasosConfig.chatroom_name,
                user_id: wasosConfig.user_id || null,
                group: wasosConfig.group || null,
                api: {
                    key: wasosConfig.api_key || (wasosConfig.api && wasosConfig.api.key),
                    expires: wasosConfig.expires || (wasosConfig.api && wasosConfig.api.expires)
                }
            },
            timestamps: { last_rayvn: 0, last_wasos: 0 },
            active: true
        };

        d.connections.push(conn);
        global.set("parat_bridge", d);
        return conn;
    },

    updateConnection: function(connectionId, updates) {
        const d = global.get("parat_bridge");
        const conn = d.connections.find(c => c.id === connectionId);
        if (!conn) return null;
        Object.assign(conn, updates);
        global.set("parat_bridge", d);
        return conn;
    },

    // --- Timestamps ---
    setTimestamp: function(connectionId, client, timestamp) {
        const d = global.get("parat_bridge");
        const conn = d.connections.find(c => c.id === connectionId);
        if (!conn) return;
        conn.timestamps["last_" + client] = timestamp;
        global.set("parat_bridge", d);
    },

    // --- Queue (one array - filter on target) ---
    enqueue: function(entry) {
        const d = global.get("parat_bridge");
        entry.retryCount = entry.retryCount || 0;
        entry.createdAt = entry.createdAt || new Date().toISOString();
        entry.lastError = entry.lastError || null;
        d.queue.push(entry);
        global.set("parat_bridge", d);
        return entry;
    },

    dequeue: function(entryId) {
        const d = global.get("parat_bridge");
        const idx = d.queue.findIndex(e => e.id === entryId);
        if (idx === -1) return null;
        const entry = d.queue.splice(idx, 1)[0];
        global.set("parat_bridge", d);
        return entry;
    },

    getQueue: function(target) {
        const d = global.get("parat_bridge");
        if (target) return d.queue.filter(e => e.target === target);
        return d.queue;
    },

    incrementRetry: function(entryId, error) {
        const d = global.get("parat_bridge");
        const entry = d.queue.find(e => e.id === entryId);
        if (!entry) return null;
        entry.retryCount = (entry.retryCount || 0) + 1;
        entry.lastError = error || null;
        global.set("parat_bridge", d);
        return entry;
    },

    // --- Master Log ---
    addToMasterLog: function(entry, status) {
        const d = global.get("parat_bridge");
        const logEntry = Object.assign({}, entry);

        // Remove que spesific field
        delete logEntry.retryCount;
        delete logEntry.createdAt;

        // Keep only metadat for files in que
        if (logEntry.files && logEntry.files.length > 0) {
            logEntry.attachments = logEntry.files.map(f => ({
                filename: f.filename || f.name || "unknown",
                size: f.size || (f.blob ? f.blob.length : 0) || 0,
                type: f.filetype || f.type || "unknown"
            }));
            delete logEntry.files;
        }
        if (logEntry.rayvnFileIds) {
            delete logEntry.rayvnFileIds;
        }

        // deliverystatus
        logEntry.status = status || "delivered";
        if (status === "delivered") {
            logEntry.deliveredAt = new Date().toISOString();
            delete logEntry.lastError;
        } else if (status === "failed") {
            logEntry.failedAt = new Date().toISOString();
            logEntry.lastError = entry.lastError;
        }

        // Duplicate check
        const exists = d.master_log.some(e => 
            e.id === logEntry.id && e.connection_id === logEntry.connection_id
        );
        if (!exists) {
            d.master_log.push(logEntry);
            global.set("parat_bridge", d);
        }
        return logEntry;
    },

    getMasterLog: function(connectionId) {
        const d = global.get("parat_bridge");
        if (connectionId) return d.master_log.filter(e => e.connection_id === connectionId);
        return d.master_log;
    },

    // --- Utility ---
    getBaseUrl: function(client) {
        return global.get("parat_bridge").base_urls[client];
    }
};

global.set("pb", pb);
node.log("Parat-Bridge initialized: " + data.connections.length + " connection(s), queue: " + data.queue.length);

msg.payload = data;
return msg;

// ============================================================
// NODE: "Create connection"
// TYPE: function
// LOCATION: Parat-Bridge.json
// WIRING: "Pass when both configured" → [this] → junction (→ Get Rayvn log entries)
//
// Join-node delivers msg.payload  to topics:
//   { rayvn_configured: {...rayvnConfig}, wasos_configured: {...wasosConfig} }
// ============================================================

const pb = global.get("pb");

const rayvnConfig = msg.payload.rayvn_configured;
const wasosConfig = msg.payload.wasos_configured;

if (!rayvnConfig || !wasosConfig) {
    node.error("Missing config from join - check that verify sends config payload");
    return null;
}

// Check if connection allready exists
const existing = pb.getConnections().find(c =>
    c.rayvn.log_id === rayvnConfig.log_id &&
    c.wasos.chatroom_name === wasosConfig.chatroom_name
);

let connection;
if (existing) {
    connection = pb.updateConnection(existing.id, {
        rayvn: rayvnConfig,
        wasos: wasosConfig,
        active: true
    });
    node.log("Updated connection: " + connection.label);
} else {
    connection = pb.addConnection(rayvnConfig, wasosConfig);
    node.log("Created connection: " + connection.label);
}

msg.connection = connection;
msg.payload = connection;
return msg;

const pb = global.get("pb");
const conns = pb.getConnections();

msg.payload = conns.map(c => ({
    "Navn": c.label,
    "Status": c.active ? "✅ Aktiv" : "⏸️ Inaktiv",
    "ID": c.id
}));

return msg;
